function computePrioritization(reference) {
  return prioritera(getData(), {
    referensFor: (aid, bas) => {
      if (reference === "stallningstagande") {
        const pol = policyFor(aid, bas);
        return pol && pol.med ? { median: pol.med, kalla: referensKortnamn() } : null;
      }
      const sr = statistikFor(state.statistik, aid, bas)?.rad;
      return sr && sr.median > 0 ? { median: sr.median, kalla: "jämförelsestatistiken" } : null;
    },
    kTroskel: kTroskel(),
    prioConfig: state.prioConfig,
    prioWeights: state.prioWeights,
    costSettings: state.costSettings,
    bristAids: state.bristAids
  });
}
function generateMotivationSuggestions(item) {
  return motiveringsgrunder(item, {
    kInstalld: kInstalld(),
    kTroskel: kTroskel(),
    mdePct: state.powerAnalysis?.mdePct,
    naraGrans: state.prioConfig.bevakaThreshold
  }).map((g) => ({ type: g.type, text: _motiveringText(g) }));
}
function _motiveringText(g) {
  switch (g.kod) {
    case "underlag":
      return `Underlaget är litet (${g.kvN} kvinnor / ${g.maN} män; minsta gruppstorlek ${g.k}). Skillnaden kan inte säkerställas statistiskt — ett tips är att överväga att slå ihop med en näraliggande BAS-grupp eller titta på individerna var för sig.`;
    case "styrka":
      return `Skillnaden (${svPct(g.diffPct, 1)}) ligger under detektionströskeln (~${svPct(g.mdePct, 1)}). Det innebär att skillnaden är så liten att den inte med säkerhet kan skiljas från slumpmässiga variationer.`;
    case "alder":
      return `${g.medelMa > g.medelKv ? "Männen" : "Kvinnorna"} är i snitt <strong>${svTal(Math.abs(g.medelMa - g.medelKv), 1)} år äldre</strong> än motparten i denna grupp (${svTal(g.medelMa, 0)} mot ${svTal(g.medelKv, 0)}). Stäm av om åldersskillnaden förklarar en del av löneskillnaden. Erfarenhet och tid i yrket är ofta sakliga skäl för löneskillnader.`;
    case "kvintil":
      return `<strong>Mönster med glastak eller klibbigt golv:</strong> ${svPct(g.andelKv * 100, 0)} av kvinnorna i denna grupp ligger i den lägsta lönekvintilen, jämfört med ${svPct(g.andelMa * 100, 0)} av männen. Det kan vara värdefullt att titta närmare på hur karriärvägar, befordringar och lönesättningsbeslut ser ut för gruppen.`;
    case "brist":
      return "Markerat som <strong>bristyrke</strong>. Marknadsläge (rekryteringssvårighet) kan vara ett sakligt skäl — dokumentera gärna marknadsläget med stöd av extern statistik (t.ex. från SCB lönestrukturstatistik).";
    case "snabbVinst": {
      const K = prioKonstanter();
      return `<strong>Snabb vinst:</strong> gruppen ligger mer än ${svPct(K.SNABB_VINST_AVVIKELSE, 0)} under referensen, och kostnaden per person är under ${svKr(K.SNABB_VINST_KR)} per månad (${g.n} personer). Lämplig för pilotåtgärd för att visa förändringsvilja.`;
    }
    case "over":
      return `Ligger ${svPct(g.diffPct, 1)} över referensen. Dokumentera gärna varför.`;
    default:
      return `Gruppens median ligger inom ±${svTal(g.nara, g.nara % 1 ? 1 : 0)} % av referensen.`;
  }
}
