function _forecastReadControls() {
  const bm = document.getElementById("forecast-budget-mode");
  const bv = document.getElementById("forecast-budget-value");
  const gm = document.getElementById("forecast-generell-mode");
  const gv = document.getElementById("forecast-generell-value");
  if (bm) state.forecast.budget.mode = /** @type {HTMLInputElement} */
  bm.value;
  if (bv) state.forecast.budget.value = /** @type {HTMLInputElement} */
  bv.value === "" ? null : parseFloat(
    /** @type {HTMLInputElement} */
    bv.value
  );
  if (gm) state.forecast.generell.mode = /** @type {HTMLInputElement} */
  gm.value;
  if (gv) state.forecast.generell.value = /** @type {HTMLInputElement} */
  gv.value === "" ? null : parseFloat(
    /** @type {HTMLInputElement} */
    gv.value
  );
  const mn = document.getElementById("forecast-min-n");
  if (mn) {
    const v = parseInt(
      /** @type {HTMLInputElement} */
      mn.value,
      10
    );
    state.forecast.minGroupN = isFinite(v) && v >= 0 ? v : 0;
  }
  const rs = document.getElementById("forecast-round");
  if (rs) {
    const v = parseInt(
      /** @type {HTMLInputElement} */
      rs.value,
      10
    );
    state.forecast.roundStep = isFinite(v) && v >= 0 ? v : 0;
  }
  const yr = document.getElementById("forecast-years");
  if (yr) {
    const v = parseInt(
      /** @type {HTMLInputElement} */
      yr.value,
      10
    );
    state.forecast.years = isFinite(v) && v >= 1 ? v : 1;
  }
}
function _forecastAidsForBas(bas) {
  const seen = /* @__PURE__ */ new Map(), iBas = getData().filter((r) => r.bas === bas);
  const namnrad = namnrader(iBas, (r) => r.aid);
  iBas.forEach((r) => {
    let g = seen.get(r.aid);
    if (!g) {
      g = { aid: r.aid, label: (namnrad.get(r.aid).yrkeLabel || r.aid || "").toString(), n: 0 };
      seen.set(r.aid, g);
    }
    g.n++;
  });
  return [...seen.values()].sort((a, b) => a.label.localeCompare(b.label, "sv"));
}
