    const lvlOpts = [["median", "BAS-median"], ["p25", "BAS P25"]].map(([v, l]) => `<option value="${v}"${tg.targetLevel === v ? " selected" : ""}>${l}</option>`).join("");
    const konOpts = [["alla", "Alla"], ["kvinna", "Bara kvinnor"], ["man", "Bara män"]].map(([v, l]) => `<option value="${v}"${(tg.kon || "alla") === v ? " selected" : ""}>${l}</option>`).join("");
    const till = tg.mode === "till";
