  return [
    n ? `${n} ${n === 1 ? "grupp visas" : "grupper visas"} inte: ${lika.utelamnade.join(", ")}. ${n === 1 ? "Den har" : "De har"} färre än ${k} ${personOrd(k)}, och ${n === 1 ? "dess" : "deras"} lönemått skulle kunna peka ut enskilda.` : "",
    m ? `${m} ${m === 1 ? "grupp har" : "grupper har"} färre än två kvinnor eller två män och jämförs inte.` : ""
  ].filter(Boolean).join(" ");
