  return `<p class="text-dampad-sm marg-0-0-6"><strong>${esc(lonemanadText())}</strong></p>` + (rader.length ? `<div class="table-container"><table id="${id}" class="data-table" data-aidbas-fil="${esc(fil)}"><thead><tr>${kolumner.map(([namn, typ, , kol]) => `<th${kol ? ` data-kol="${kol}"` : ""}${typ === "text" ? "" : ' class="tal"'}${namn === _STS_DIR_KOLUMN ? ` title="${esc(_STS_DIR_TIPS)}"` : ""}>${esc(namn)}</th>`).join("")}</tr></thead><tbody>${kropp}</tbody></table></div>` : `<p class="text-dampad-sm">${esc(tom)}</p>`) + (not ? `<p class="text-dampad-xs marg-8-0-0">${esc(not)}</p>` : "");
