  lines.push("");
  lines.push("Löneskillnad (kvinnors lön i procent av mäns):");
  if (ctx.konOk) lines.push(`  • Kvinnors genomsnittslön är ${andelAvMan(ctx.meanGap)} av mäns, och medianlönen ${andelAvMan(ctx.medGap)} av mäns.`);
