function policyFor(aid, bas) {
  const pol = state.policy || [];
  if (!pol.length) return null;
  const a = aid == null || aid === "" ? null : String(aid).trim();
  const b = bas == null || bas === "" ? null : String(bas).trim();
  let hit = null;
  if (a && b) {
    hit = pol.find((p) => p.aid === a && p.bas === b);
    if (hit) return hit;
  }
  if (a) {
    hit = pol.find((p) => p.aid === a && !p.bas);
    if (hit) return hit;
  }
  if (b) {
    hit = pol.find((p) => p.bas === b && !p.aid);
    if (hit) return hit;
  }
  return null;
}
